using System;using System.Linq;using System.Drawing;using System.Reflection;using System.Threading;using System.Windows.Forms;using System.IO;
namespace Frociart.Tests {
static class LearningFlowTests {
 static BindingFlags F=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance;static int checks;
 static void Check(bool b,string text){if(!b)throw new Exception(text);checks++;Console.WriteLine("PASS "+text);}
 static T Get<T>(object o,string n){return(T)o.GetType().GetField(n,F).GetValue(o);}
 static object Call(object o,string n,params object[] a){return o.GetType().GetMethods(F).First(m=>m.Name==n&&m.GetParameters().Length==a.Length).Invoke(o,a);}
 static void Set(object o,string n,object v){o.GetType().GetField(n,F).SetValue(o,v);}
 static void Pump(int ms=30){var until=DateTime.UtcNow.AddMilliseconds(ms);do{Application.DoEvents();Thread.Sleep(2);}while(DateTime.UtcNow<until);}
 static void Wait(Func<bool> f,string text){for(int i=0;i<500;i++){Pump(20);if(f()){Check(true,text);return;}}throw new Exception(text);}
 static void Capture(Control c,string n){var dir=Environment.GetEnvironmentVariable("REVIEW_OUTPUT");Directory.CreateDirectory(dir);using(var b=new Bitmap(c.Width,c.Height)){c.DrawToBitmap(b,new Rectangle(Point.Empty,c.Size));b.Save(Path.Combine(dir,n+".png"));}}
 static void Finish(TutorDialog d,TutorLesson l,bool fast=false){int input=0;for(int i=0;i<2050;i++){var r=Get<Interpreter>(d,"runner");if(r.State==RuntimeState.Completed)return;if(r.State==RuntimeState.Error)throw new Exception(r.Error);if(r.State==RuntimeState.WaitingForInput){Get<TextBox>(d,"runInput").Text=l.trials[0].inputs[input++%l.trials[0].inputs.Length];Call(d,"SubmitRun");}else if(!fast)Get<FlowButton>(d,"stepRun").PerformClick();Pump(fast?20:5);}throw new Exception("Runner limit");}
 [STAThread]static int Main(){try{Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);UiMotion.SetEnabled(true);Ui.SetDarkMode(true,false);var store=new TutorStore();
 foreach(var l in Tutor.Lessons){var seed=store.Load(l.id,l.Seed());seed.Document=l.Solution();seed.Completed=seed.Demonstrated=false;seed.Step=0;Check(store.Save(seed),"Isolated solved fixture "+l.id);
 using(var d=new TutorDialog(store,new LearningStore())){d.ShowInTaskbar=false;d.StartPosition=FormStartPosition.Manual;d.Location=new Point(-2500,-1800);d.Show();Pump(350);d.SelectLesson(l.id);Get<FlowButton>(d,"primary").PerformClick();Pump(350);
 var tools=Get<Control>(d,"trialTools");if(l.id=="b13"){d.Size=new Size(1050,720);Pump(400);Check(tools.Controls.Cast<Control>().Where(c=>c.Visible).All(c=>tools.ClientRectangle.Contains(c.Bounds)),"Top commands fit the minimum supported window");Capture(d,"learning-toolbar-minimum");int width=d.Canvas.Width;Get<FlowButton>(d,"expandTutor").PerformClick();Pump(400);Check(d.Canvas.Width>width&&!Get<TabControl>(d,"inspectorTabs").Visible,"PNG expands the desktop canvas");Get<FlowButton>(d,"expandTutor").PerformClick();Pump(400);Check(Get<TabControl>(d,"inspectorTabs").Visible,"PNG restores editor panels");Check(!Get<FlowScrollPanel>(d,"editor").HorizontalScroll.Visible,"Restoring panels preserves width without horizontal overflow");}Check(tools.PointToScreen(Point.Empty).Y<d.Canvas.PointToScreen(Point.Empty).Y,"Drawing commands above canvas "+l.id);Check(Get<FlowButton>(d,"expandTutor").Image!=null,"Actual PNG expand icon "+l.id);
 Set(d,"finalRequested",true);Call(d,"CheckCurrent");Wait(()=>d.Feedback!=null,"Final real check "+l.id);Check(d.Feedback.Pass&&!d.Current.Completed,"Check success alone does not complete "+l.id);Check(Get<TabControl>(d,"inspectorTabs").SelectedIndex==1,"Check opens execution "+l.id);Check(!Get<FlowButton>(d,"skipRun").Visible,"First demonstration has no skip "+l.id);Check(Get<FlowButton>(d,"stepRun").Text=="Avanti","Avanti label "+l.id);
 Call(d,"CompleteVerifiedRun");Check(!d.Current.Completed,"No completion bypass "+l.id);if(l.id=="b13"){Capture(d,"learning-first-execution");Call(d,"FinishTrial");Get<FlowButton>(d,"primary").PerformClick();Check(Get<TabControl>(d,"inspectorTabs").SelectedIndex==1,"Incomplete demonstration resumes");}
 Finish(d,l);Check(d.Current.Demonstrated&&!d.Current.Completed,"Completed execution remembers first demonstration "+l.id);Check(Get<FlowButton>(d,"continueRun").Visible,"Continuation only after completion "+l.id);Get<FlowButton>(d,"continueRun").PerformClick();Check(store.Peek(l.id).Completed,"Completion durable after execution "+l.id);d.Close();}
 }
 var lesson=Tutor.Lesson("b13");using(var d=new TutorDialog(store,new LearningStore())){d.ShowInTaskbar=false;d.StartPosition=FormStartPosition.Manual;d.Location=new Point(-2500,-1800);d.Show();Pump(350);d.SelectLesson(lesson.id);Get<FlowButton>(d,"primary").PerformClick();Set(d,"finalRequested",true);Call(d,"CheckCurrent");Wait(()=>d.Feedback!=null,"Repeat check");Check(Get<FlowButton>(d,"skipRun").Visible,"Repeat offers skip");Get<FlowButton>(d,"skipRun").PerformClick();Wait(()=>Get<Interpreter>(d,"runner").State==RuntimeState.WaitingForInput,"Fast execution still asks actual Input");Capture(d,"learning-repeat-input");Finish(d,lesson,true);Check(Get<Interpreter>(d,"runner").State==RuntimeState.Completed,"Fast mode produces actual result");Capture(d,"learning-repeat-result");d.Close();}
 foreach(var l in Tutor.Lessons){var graph=l.Solution();var n=graph.Nodes.FirstOrDefault(x=>x.Kind==NodeKind.Decision);if(n==null)continue;var incoming=graph.Edges.First(e=>e.To==n.Id);string source=incoming.From;graph.Edges.Remove(incoming);foreach(var x in graph.Nodes){x.X+=137;x.Y+=49;}string before=String.Join(";",graph.Nodes.Select(x=>x.Id+"/"+x.X+"/"+x.Y));Check(Tutor.Connect(graph,source,"next",n.Id),"Decision reconnect "+l.id);Check(before==String.Join(";",graph.Nodes.Select(x=>x.Id+"/"+x.X+"/"+x.Y)),"Decision reconnect preserves every position "+l.id);}
 using(var f=new Form{Size=new Size(1000,760),ShowInTaskbar=false,StartPosition=FormStartPosition.Manual,Location=new Point(-2500,-1800)})using(var c=new FlowCanvas{Dock=DockStyle.Fill,Diagram=Examples.Parity()}){f.Controls.Add(c);f.Show();Pump(350);c.FitToView();Pump(100);var n=c.Diagram.Nodes.First(x=>x.Kind==NodeKind.Decision);var r=FlowCanvas.GetNodeBounds(n);var at=Point.Round(c.WorldToClient(new PointF(r.X+r.Width/2,r.Y+r.Height/2)));string status="";c.StatusChanged+=delegate(object sender,StatusEventArgs e){status=e.Message;};Call(c,"OnMouseDown",new MouseEventArgs(MouseButtons.Left,1,at.X,at.Y,0));Pump(230);Check(status!="Tieni premuto","Normal click has no immediate hold message");Pump(290);Check(status=="Tieni premuto","Hold hint appears after 400 ms on PC");Check(Get<float>(c,"holdFill")==0,"Hint does not shorten the hold grace");Call(c,"OnMouseUp",new MouseEventArgs(MouseButtons.Left,1,at.X,at.Y,0));Pump(200);f.Close();}
 Console.WriteLine("LEARNING_FLOW_FINISHED checks="+checks+" lessons=24 errors=0");return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}}
